Here's a basic Python example using `requests` and `urllib3`:

```python
import requests
from urllib3.exceptions import InsecureRequestWarning

# Set up your proxy/target
proxies = {"http": "http://your-proxy:8080", "https": "http://your-proxy:8080"}

def deny_access(target, method="GET", url=None):
    headers = {"User-Agent": "Mozilla/5.0"}

    try:
        response = requests.request(method, target, proxies=proxies, headers=headers).status_code
        message = f"Access denied: {response}"

        if response != 200:
            raise ValueError(f"Request failed: {response}")

        return {"status": "denied", "message": message}
    except Exception as e:
        return {"status": "error", "message": str(e)}

# Usage
result = deny_access("https://example.com", "GET")
print(result)
